// ServerInterface represents all server handlers.
type ServerInterface interface {
	// PostAuthClaim Create an account with a school access code
	// (POST /auth/claim)
	PostAuthClaim(w http.ResponseWriter, r *http.Request)
	// PostAuthEmailVerification Email a verification link to the signed-in user
	// (POST /auth/email/verification)
	PostAuthEmailVerification(w http.ResponseWriter, r *http.Request)
	// PostAuthEmailVerify Confirm the email address with an emailed token
	// (POST /auth/email/verify)
	PostAuthEmailVerify(w http.ResponseWriter, r *http.Request)
	// PostAuthLink Email a sign-in link
	// (POST /auth/link)
	PostAuthLink(w http.ResponseWriter, r *http.Request)
	// PostAuthLinkConsume Sign in with an emailed link
	// (POST /auth/link/consume)
	PostAuthLinkConsume(w http.ResponseWriter, r *http.Request)
	// PostAuthLogin Sign in with email and password
	// (POST /auth/login)
	PostAuthLogin(w http.ResponseWriter, r *http.Request)
	// PostAuthLogout Sign out
	// (POST /auth/logout)
	PostAuthLogout(w http.ResponseWriter, r *http.Request)
	// GetAuthMe Current user
	// (GET /auth/me)
	GetAuthMe(w http.ResponseWriter, r *http.Request)
	// PostAuthMfaEnrollment Start (or restart) TOTP enrollment
	// (POST /auth/mfa/enrollment)
	PostAuthMfaEnrollment(w http.ResponseWriter, r *http.Request)
	// PostAuthMfaEnrollmentConfirm Confirm TOTP enrollment with a first code
	// (POST /auth/mfa/enrollment/confirm)
	PostAuthMfaEnrollmentConfirm(w http.ResponseWriter, r *http.Request)
	// PostAuthMfaVerify Complete two-factor sign-in
	// (POST /auth/mfa/verify)
	PostAuthMfaVerify(w http.ResponseWriter, r *http.Request)
	// PostAuthPassword Change the password of the signed-in user
	// (POST /auth/password)
	PostAuthPassword(w http.ResponseWriter, r *http.Request)
	// PostAuthPasswordReset Set a new password with an emailed token
	// (POST /auth/password/reset)
	PostAuthPasswordReset(w http.ResponseWriter, r *http.Request)
	// PostAuthPasswordResetRequest Email a password reset link
	// (POST /auth/password/reset-request)
	PostAuthPasswordResetRequest(w http.ResponseWriter, r *http.Request)
	// PostAuthRedeem Add a school to the signed-in account with an access code
	// (POST /auth/redeem)
	PostAuthRedeem(w http.ResponseWriter, r *http.Request)
	// GetContacts List contacts of the active school
	// (GET /contacts)
	GetContacts(w http.ResponseWriter, r *http.Request, params GetContactsParams)
	// PostContact Create a contact
	// (POST /contacts)
	PostContact(w http.ResponseWriter, r *http.Request)
	// GetContactHeadings List contact headings of the active school
	// (GET /contacts/headings)
	GetContactHeadings(w http.ResponseWriter, r *http.Request)
	// PostContactHeading Create a contact heading
	// (POST /contacts/headings)
	PostContactHeading(w http.ResponseWriter, r *http.Request)
	// DeleteContactHeading Delete an unused contact heading
	// (DELETE /contacts/headings/{id})
	DeleteContactHeading(w http.ResponseWriter, r *http.Request, id string)
	// PatchContactHeading Rename a contact heading
	// (PATCH /contacts/headings/{id})
	PatchContactHeading(w http.ResponseWriter, r *http.Request, id string)
	// PostContactHeadingArchive Archive a contact heading
	// (POST /contacts/headings/{id}/archive)
	PostContactHeadingArchive(w http.ResponseWriter, r *http.Request, id string)
	// DeleteContact Delete a contact
	// (DELETE /contacts/{id})
	DeleteContact(w http.ResponseWriter, r *http.Request, id string)
	// PatchContact Update a contact
	// (PATCH /contacts/{id})
	PatchContact(w http.ResponseWriter, r *http.Request, id string)
	// PostContactReferencePrice Add a dated reference price to a contact
	// (POST /contacts/{id}/reference-prices)
	PostContactReferencePrice(w http.ResponseWriter, r *http.Request, id string)
	// DeleteContactReferencePrice Delete a reference price from a contact
	// (DELETE /contacts/{id}/reference-prices/{priceId})
	DeleteContactReferencePrice(w http.ResponseWriter, r *http.Request, id string, priceId string)
	// PostElection Create the draft of an election
	// (POST /elections)
	PostElection(w http.ResponseWriter, r *http.Request)
	// GetCurrentElection Read the active school's election in progress (neither published nor annulled)
	// (GET /elections/current)
	GetCurrentElection(w http.ResponseWriter, r *http.Request)
	// GetElection Read an election of the active school
	// (GET /elections/{electionId})
	GetElection(w http.ResponseWriter, r *http.Request, electionId string)
	// PutElection Edit the draft of an election
	// (PUT /elections/{electionId})
	PutElection(w http.ResponseWriter, r *http.Request, electionId string)
	// GetElectoralCommission Read the active school's current Electoral commission
	// (GET /electoral-commission)
	GetElectoralCommission(w http.ResponseWriter, r *http.Request)
	// PutElectoralCommission Designate or replace the members of the current Electoral commission
	// (PUT /electoral-commission)
	PutElectoralCommission(w http.ResponseWriter, r *http.Request)
	// GetElectoralCommissionCandidates List the roster members who can sit on the Electoral commission
	// (GET /electoral-commission/candidates)
	GetElectoralCommissionCandidates(w http.ResponseWriter, r *http.Request)
	// GetEventBudgets List event budgets
	// (GET /event-budgets)
	GetEventBudgets(w http.ResponseWriter, r *http.Request)
	// PostEventBudget Create an event budget
	// (POST /event-budgets)
	PostEventBudget(w http.ResponseWriter, r *http.Request)
	// DeleteEventBudget Delete an event budget without linked entries
	// (DELETE /event-budgets/{id})
	DeleteEventBudget(w http.ResponseWriter, r *http.Request, id string)
	// GetEventBudget Get an event budget and calculated totals
	// (GET /event-budgets/{id})
	GetEventBudget(w http.ResponseWriter, r *http.Request, id string)
	// PutEventBudget Update an event budget
	// (PUT /event-budgets/{id})
	PutEventBudget(w http.ResponseWriter, r *http.Request, id string)
	// PostEventBudgetArchive Archive an event budget
	// (POST /event-budgets/{id}/archive)
	PostEventBudgetArchive(w http.ResponseWriter, r *http.Request, id string)
	// PostEventBudgetLine Add a budget line
	// (POST /event-budgets/{id}/lines)
	PostEventBudgetLine(w http.ResponseWriter, r *http.Request, id string)
	// DeleteEventBudgetLine Delete a budget line
	// (DELETE /event-budgets/{id}/lines/{lineId})
	DeleteEventBudgetLine(w http.ResponseWriter, r *http.Request, id string, lineId string)
	// PutEventBudgetLine Replace a budget line
	// (PUT /event-budgets/{id}/lines/{lineId})
	PutEventBudgetLine(w http.ResponseWriter, r *http.Request, id string, lineId string)
	// GetFinanceBalance Fund balance in cents
	// (GET /finance/balance)
	GetFinanceBalance(w http.ResponseWriter, r *http.Request)
	// GetFinanceCategories List categories in the active school
	// (GET /finance/categories)
	GetFinanceCategories(w http.ResponseWriter, r *http.Request)
	// GetFinanceEntries List entries in the active school
	// (GET /finance/entries)
	GetFinanceEntries(w http.ResponseWriter, r *http.Request)
	// PostFinanceEntries Record an income or expense as an officer with MFA
	// (POST /finance/entries)
	PostFinanceEntries(w http.ResponseWriter, r *http.Request)
	// GetFinanceEntry Get an entry in the active school
	// (GET /finance/entries/{entryId})
	GetFinanceEntry(w http.ResponseWriter, r *http.Request, entryId string)
	// PostFinanceEntryReversal Reverse an entry as any officer with MFA
	// (POST /finance/entries/{entryId}/reversal)
	PostFinanceEntryReversal(w http.ResponseWriter, r *http.Request, entryId string)
	// GetHealth Liveness check
	// (GET /health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// GetMembers List accounts and unclaimed officers in the active school
	// (GET /members)
	GetMembers(w http.ResponseWriter, r *http.Request)
	// DeleteMemberOfficer Remove an officer position
	// (DELETE /members/{memberId}/officer)
	DeleteMemberOfficer(w http.ResponseWriter, r *http.Request, memberId string)
	// PostMemberOfficer Assign an officer position to a roster member
	// (POST /members/{memberId}/officer)
	PostMemberOfficer(w http.ResponseWriter, r *http.Request, memberId string)
	// GetRoster List the roster of the active tenant
	// (GET /roster)
	GetRoster(w http.ResponseWriter, r *http.Request)
	// PostRosterAccessCodes Issue codes for every member without an account and without an active code
	// (POST /roster/access-codes)
	PostRosterAccessCodes(w http.ResponseWriter, r *http.Request)
	// PostRosterImport Import roster members from CSV
	// (POST /roster/import)
	PostRosterImport(w http.ResponseWriter, r *http.Request)
	// PostRosterMemberAccessCode Issue an access code for one roster member
	// (POST /roster/{memberId}/access-code)
	PostRosterMemberAccessCode(w http.ResponseWriter, r *http.Request, memberId string)
}

